const https = require('https');

const serviceRole =
  $env.P6C_SUPABASE_SERVICE_ROLE_KEY;

if (
  typeof serviceRole !== 'string' ||
  serviceRole.length < 20
) {
  throw new Error(
    'P6C_SUPABASE_SERVICE_ROLE_KEY is unavailable'
  );
}

const body = JSON.stringify({
  p_worker_id:
    'n8n-phase6d-inbound-sms-worker',

  p_event_types: [
    'TWILIO_INCOMING_MESSAGE',
  ],

  p_limit: 10,

  p_lock_timeout_seconds: 300,
});

const response = await new Promise(
  (resolve, reject) => {
    const req = https.request(
      {
        hostname:
          'lirmmoebcvmoixxfbmlu.supabase.co',

        port: 443,

        path:
          '/rest/v1/rpc/claim_outbox_events_v1',

        method: 'POST',

        headers: {
          apikey: serviceRole,

          Authorization:
            `Bearer ${serviceRole}`,

          'Content-Type':
            'application/json',
        },

        timeout: 15000,
      },

      (res) => {
        let data = '';

        res.on(
          'data',
          (chunk) => {
            data += chunk;
          }
        );

        res.on(
          'end',
          () => {
            resolve({
              status: res.statusCode,
              body: data,
            });
          }
        );
      }
    );

    req.on(
      'timeout',
      () => {
        req.destroy(
          new Error(
            'SUPABASE_CLAIM_TIMEOUT'
          )
        );
      }
    );

    req.on(
      'error',
      reject
    );

    req.write(body);
    req.end();
  }
);

if (
  response.status < 200 ||
  response.status >= 300
) {
  throw new Error(
    `SUPABASE_CLAIM_HTTP_${response.status}: ${response.body}`
  );
}

const rows =
  response.body.trim() === ''
    ? []
    : JSON.parse(response.body);

if (!Array.isArray(rows)) {
  throw new Error(
    'SUPABASE_CLAIM_RESPONSE_NOT_ARRAY'
  );
}

return rows.map(
  (row) => ({
    json: row,
  })
);

const https = require('https');

const serviceRole =
  $env.P6C_SUPABASE_SERVICE_ROLE_KEY;

if (
  typeof serviceRole !== 'string' ||
  serviceRole.length < 20
) {
  throw new Error(
    'P6C_SUPABASE_SERVICE_ROLE_KEY is unavailable'
  );
}

const workerId =
  'n8n-phase6d-inbound-sms-worker';

const inputItems =
  $input.all();

const results = [];

for (const item of inputItems) {

  const outboxEventId =
    item.json.outbox_event_id;

  if (
    typeof outboxEventId !== 'string' ||
    outboxEventId.length < 30
  ) {
    throw new Error(
      'Missing or invalid outbox_event_id'
    );
  }

  const requestBody =
    JSON.stringify({
      p_outbox_event_id:
        outboxEventId,

      p_worker_id:
        workerId,
    });

  let response;

  try {
    response =
      await new Promise(
        (resolve, reject) => {

          const req =
            https.request(
              {
                hostname:
                  'lirmmoebcvmoixxfbmlu.supabase.co',

                port: 443,

                path:
                  '/rest/v1/rpc/reconcile_twilio_incoming_message_v1',

                method:
                  'POST',

                headers: {
                  apikey:
                    serviceRole,

                  Authorization:
                    `Bearer ${serviceRole}`,

                  'Content-Type':
                    'application/json',
                },

                timeout:
                  15000,
              },

              (res) => {
                let data = '';

                res.on(
                  'data',
                  (chunk) => {
                    data += chunk;
                  }
                );

                res.on(
                  'end',
                  () => {
                    resolve({
                      status:
                        res.statusCode,

                      body:
                        data,
                    });
                  }
                );
              }
            );

          req.on(
            'timeout',
            () => {
              req.destroy(
                new Error(
                  'SUPABASE_RECONCILE_TIMEOUT'
                )
              );
            }
          );

          req.on(
            'error',
            reject
          );

          req.write(
            requestBody
          );

          req.end();
        }
      );
  } catch (error) {

    results.push({
      json: {
        outbox_event_id:
          outboxEventId,

        next_action:
          'FAIL_OUTBOX',

        reason_code:
          error?.message ===
          'SUPABASE_RECONCILE_TIMEOUT'
            ? 'SUPABASE_RECONCILE_TIMEOUT'
            : 'SUPABASE_RECONCILE_NETWORK_ERROR',

        retry_after_seconds:
          60,
      },
    });

    continue;
  }


  if (
    response.status < 200 ||
    response.status >= 300
  ) {

    results.push({
      json: {
        outbox_event_id:
          outboxEventId,

        next_action:
          'FAIL_OUTBOX',

        reason_code:
          `SUPABASE_RECONCILE_HTTP_${response.status}`,

        retry_after_seconds:
          response.status >= 500
            ? 60
            : 300,
      },
    });

    continue;
  }


  let rows;

  try {
    rows =
      response.body.trim() === ''
        ? []
        : JSON.parse(
            response.body
          );
  } catch {

    results.push({
      json: {
        outbox_event_id:
          outboxEventId,

        next_action:
          'FAIL_OUTBOX',

        reason_code:
          'SUPABASE_RECONCILE_INVALID_JSON',

        retry_after_seconds:
          60,
      },
    });

    continue;
  }


  if (
    !Array.isArray(rows) ||
    rows.length !== 1
  ) {

    results.push({
      json: {
        outbox_event_id:
          outboxEventId,

        next_action:
          'FAIL_OUTBOX',

        reason_code:
          'SUPABASE_RECONCILE_RESPONSE_INVALID',

        retry_after_seconds:
          60,
      },
    });

    continue;
  }


  results.push({
    json:
      rows[0],
  });
}

return results;

